def rank_transform(values: list[float]) -> list[float]:
    """Average ranks (1-based; ties share the mean of the ranks they occupy)."""
    n: int = len(values)
    ranks: list[float] = []
    for i in range(n):
        below: int = 0
        equal: int = 0
        for j in range(n):
            if values[j] < values[i]:
                below += 1
            elif values[j] == values[i]:
                equal += 1
        ranks.append(below + (equal + 1) / 2.0)
    return ranks

